def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    moving = []

    # Move each colored object in the right room up one cell, unless
    # it already touches the room's ceiling.
    for r in range(1, h - 1):
        for c in range(10, min(19, w - 1)):
            value = grid[r][c]
            if value in (0, 5) or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (1 <= nr < h - 1 and 10 <= nc < min(19, w - 1)
                            and (nr, nc) not in seen
                            and grid[nr][nc] == value):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            if min(rr for rr, _ in component) > 1:
                moving.append((value, component))

    for _, component in moving:
        for r, c in component:
            out[r][c] = 0
    for value, component in moving:
        for r, c in component:
            out[r - 1][c] = value

    # Transfer the 5-pattern from the left panel into the right room.
    for r in range(h):
        for c in range(min(9, w)):
            target = c + 10
            if grid[r][c] == 5 and target < w - 1:
                out[r][target] = 5

    # Clear the original pattern.
    for r in range(h):
        for c in range(min(9, w)):
            out[r][c] = 0

    return out
